// --- bundled from src/tranche-projection-snapshot.ts ---
/** Compact persisted digest of tranche projection readiness at seal (round 20). */
export function computeTrancheProjectionSnapshot(
  outlook: ResearchTrancheProjectionReadinessOutlook,
  turn: number
): ResearchTrancheProjectionSnapshot {
  const trancheReadinessScore = Math.round(
    Math.min(100, Math.max(0, outlook.trancheReadinessScore ?? 0))
  );
  const projectionMomentum = Math.round(Math.min(100, Math.max(0, outlook.projectionMomentum ?? 0)));
  let peakBand = 0;
  for (const band of RESEARCH_TRANCHE_PROJECTION_BANDS) {
    if (trancheReadinessScore >= band) peakBand = band;
  }
  const payload = `t${turn}|r${trancheReadinessScore}|h${outlook.horizonTurns}|w${outlook.waveOrdinal}|m${projectionMomentum}|d${outlook.dryRunEligible ? 1 : 0}`;
  let h = 2166136261 >>> 0;
  for (let i = 0; i < payload.length; i++) {
    h ^= payload.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return {
    capturedAtTurn: turn,
    trancheReadinessScore,
    horizonTurns: outlook.horizonTurns,
    waveOrdinal: outlook.waveOrdinal,
    projectionMomentum,
    dryRunEligible: outlook.dryRunEligible,
    peakBand: peakBand as ResearchTrancheProjectionSnapshot['peakBand'],
    digest: h.toString(36),
  };
}

export function mergeTrancheProjectionSnapshots(
  local: ResearchTrancheProjectionSnapshot | undefined,
  remote: ResearchTrancheProjectionSnapshot | undefined
): ResearchTrancheProjectionSnapshot | undefined {
  if (!local && !remote) return undefined;
  if (!local) return remote;
  if (!remote) return local;
  return local.capturedAtTurn >= remote.capturedAtTurn ? local : remote;
}

// --- bundled from src/scale-wave-integration-gate-outlook.ts ---
/** Wave 20 integration gate for Agent 25 O10-171 dry-run (read-only, round 20 / O10-170). */
export function computeResearchScaleWaveIntegrationGateOutlook(
  inputs: ResearchProgressInputs,
  ctx: Pick<
    ResearchProgressState,
    | 'trancheProjectionReadinessOutlook'
    | 'scaleWaveProjectionOutlook'
    | 'trancheProjectionSnapshot'
    | 'scaleWaveProjectionSnapshot'
  >
): ResearchScaleWaveIntegrationGateOutlook {
  const tranche = ctx.trancheProjectionReadinessOutlook;
  const projection = ctx.scaleWaveProjectionOutlook;
  const horizonTurns = tranche?.horizonTurns ?? projection?.horizonTurns ?? 6;
  const waveOrdinal = 20;

  const trancheScore = tranche?.trancheReadinessScore ?? 0;
  const projectionScore = projection?.projectionReadinessScore ?? 0;
  const priorTranchePeak = ctx.trancheProjectionSnapshot?.peakBand ?? 0;
  const gateMomentum = Math.max(0, trancheScore - priorTranchePeak * 0.32);

  const integrationGateScore = Math.min(
    100,
    Math.round(
      trancheScore * 0.4 +
        projectionScore * 0.28 +
        gateMomentum * 0.17 +
        (tranche?.dryRunEligible ? 10 : 0) +
        (ctx.scaleWaveProjectionSnapshot?.peakBand ?? 0) * 0.05
    )
  );

  const dryRunEligible =
    inputs.turn >= waveOrdinal ||
    integrationGateScore >= 60 ||
    (tranche?.dryRunEligible && trancheScore >= 55);

  return {
    active:
      dryRunEligible ||
      (tranche?.active ?? false) ||
      integrationGateScore > 0 ||
      (projection?.active ?? false),
    baseTurn: inputs.turn,
    horizonTurns,
    waveOrdinal,
    integrationGateScore,
    gateMomentum: Math.round(gateMomentum),
    integrationBaselineShaHint: '680b9954',
    dryRunEligible,
    ticketHint: dryRunEligible ? 'O10-171' : null,
  };
}

// --- bundled from src/tranche-dry-run-handoff-outlook.ts ---
/** Agent 25 post-wave dry-run handoff signal (read-only, round 21 / O10-173). */
export function computeResearchTrancheDryRunHandoffOutlook(
  inputs: ResearchProgressInputs,
  ctx: Pick<
    ResearchProgressState,
    | 'scaleWaveIntegrationGateOutlook'
    | 'trancheProjectionReadinessOutlook'
    | 'integrationGateSnapshot'
    | 'trancheProjectionSnapshot'
  >
): ResearchTrancheDryRunHandoffOutlook {
  const gate = ctx.scaleWaveIntegrationGateOutlook;
  const tranche = ctx.trancheProjectionReadinessOutlook;
  const horizonTurns = gate?.horizonTurns ?? tranche?.horizonTurns ?? 6;
  const waveOrdinal = 21;

  const gateScore = gate?.integrationGateScore ?? 0;
  const trancheScore = tranche?.trancheReadinessScore ?? 0;
  const priorGatePeak = ctx.integrationGateSnapshot?.peakBand ?? 0;
  const handoffMomentum = Math.max(0, gateScore - priorGatePeak * 0.3);

  const handoffReadinessScore = Math.min(
    100,
    Math.round(
      gateScore * 0.42 +
        trancheScore * 0.26 +
        handoffMomentum * 0.16 +
        (gate?.dryRunEligible ? 11 : 0) +
        (ctx.trancheProjectionSnapshot?.peakBand ?? 0) * 0.06
    )
  );

  const dryRunEligible =
    inputs.turn >= waveOrdinal ||
    handoffReadinessScore >= 62 ||
    (gate?.dryRunEligible && gateScore >= 58);

  return {
    active:
      dryRunEligible ||
      (gate?.active ?? false) ||
      handoffReadinessScore > 0 ||
      (tranche?.active ?? false),
    baseTurn: inputs.turn,
    horizonTurns,
    waveOrdinal,
    handoffReadinessScore,
    handoffMomentum: Math.round(handoffMomentum),
    integrationBaselineShaHint: '99f2e72b',
    dryRunEligible,
    ticketHint: dryRunEligible ? 'O10-174' : null,
  };
}

// --- bundled from src/scale-wave-integration-gate-band-log.ts ---
export const RESEARCH_INTEGRATION_GATE_BAND_LOG_CAP = 32;

export const RESEARCH_INTEGRATION_GATE_BANDS: ResearchScaleWaveIntegrationGateBand[] = [58, 72, 86, 96];

function gateScore(outlook: ResearchScaleWaveIntegrationGateOutlook): number {
  return Math.round(Math.min(100, Math.max(0, outlook.integrationGateScore ?? 0)));
}

function highestLoggedBand(
  log: ResearchScaleWaveIntegrationGateBandEvent[],
  phase: ResearchScaleWaveIntegrationGateBandEvent['phase']
): ResearchScaleWaveIntegrationGateBand {
  let best = 0;
  for (const ev of log) {
    if (ev.phase !== phase) continue;
    if (ev.band > best) best = ev.band;
  }
  return best as ResearchScaleWaveIntegrationGateBand;
}

export function emptyIntegrationGateBandLog(): ResearchScaleWaveIntegrationGateBandEvent[] {
  return [];
}

export function appendIntegrationGateBandEvents(
  previousLog: ResearchScaleWaveIntegrationGateBandEvent[],
  previousSnapshot: ResearchScaleWaveIntegrationGateSnapshot | null,
  outlook: ResearchScaleWaveIntegrationGateOutlook,
  turn: number
): ResearchScaleWaveIntegrationGateBandEvent[] {
  const score = gateScore(outlook);
  const priorScore = previousSnapshot?.integrationGateScore ?? 0;
  const appended: ResearchScaleWaveIntegrationGateBandEvent[] = [];
  let nextSeq = previousLog.length > 0 ? Math.max(...previousLog.map(e => e.seq)) + 1 : 1;

  if (score > priorScore) {
    const floor = Math.max(highestLoggedBand(previousLog, 'escalation'), previousSnapshot?.peakBand ?? 0);
    for (const band of RESEARCH_INTEGRATION_GATE_BANDS) {
      if (band <= floor) continue;
      if (score < band) break;
      appended.push({
        seq: nextSeq++,
        turn,
        band,
        integrationGateScore: score,
        horizonTurns: outlook.horizonTurns,
        waveOrdinal: outlook.waveOrdinal,
        phase: 'escalation',
      });
    }
  } else if (score < priorScore) {
    const ceiling =
      previousSnapshot?.peakBand ??
      (highestLoggedBand(previousLog, 'escalation') ||
        RESEARCH_INTEGRATION_GATE_BANDS[RESEARCH_INTEGRATION_GATE_BANDS.length - 1]);
    for (const band of [...RESEARCH_INTEGRATION_GATE_BANDS].reverse()) {
      if (band > ceiling) continue;
      if (score > band) break;
      if (priorScore < band) continue;
      appended.push({
        seq: nextSeq++,
        turn,
        band,
        integrationGateScore: score,
        horizonTurns: outlook.horizonTurns,
        waveOrdinal: outlook.waveOrdinal,
        phase: 'de-escalation',
      });
    }
  }

  if (appended.length === 0) return previousLog.slice(-RESEARCH_INTEGRATION_GATE_BAND_LOG_CAP);
  return [...previousLog, ...appended].slice(-RESEARCH_INTEGRATION_GATE_BAND_LOG_CAP);
}

